package com.englishhero.wall;
import java.sql.Timestamp;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import com.englishhero.identity.SessionPrincipal;
import com.englishhero.web.BusinessException;
import static com.englishhero.wall.WallDtos.*;
@Service
public class WallModerationService {
 private final WallMapper mapper;private final WallInteractionMapper comments;private final WallModerationMapper moderation;private final WallCommandService commands;private final tools.jackson.databind.ObjectMapper json;
 public WallModerationService(WallMapper mapper,WallInteractionMapper comments,WallModerationMapper moderation,WallCommandService commands,tools.jackson.databind.ObjectMapper json){this.mapper=mapper;this.comments=comments;this.moderation=moderation;this.commands=commands;this.json=json;}
 @Transactional(readOnly=true)public Object list(SessionPrincipal actor,String status,boolean flagged,String cursor,int size){commands.requireAdmin(actor);WallRules.size(size);if(status!=null&&!status.isBlank())WallRules.oneOf(status,"status","VISIBLE","HIDDEN","DELETED");String sql="SELECT m.id FROM wall_message m WHERE m.id<?";var args=new ArrayList<Object>();args.add(WallRules.cursor(cursor));if(status!=null&&!status.isBlank()){sql+=" AND m.status=?";args.add(status);}if(flagged)sql+=" AND EXISTS(SELECT 1 FROM wall_report r WHERE r.message_id=m.id AND r.status='PENDING')";sql+=" ORDER BY m.id DESC LIMIT ?";args.add(size+1);var ids=mapper.sql().queryForList(sql,Long.class,args.toArray());boolean more=ids.size()>size;var items=ids.stream().limit(size).map(id->{var m=mapper.message(id,false);return Map.of("message",mapper.dto(m,actor.userId()),"status",m.status(),"pendingReports",mapper.sql().queryForObject("SELECT COUNT(*) FROM wall_report WHERE message_id=? AND status='PENDING'",Long.class,id));}).toList();return new Page<>(items,more?Long.toString(ids.get(size-1)):null,more);}
 @Transactional(readOnly=true)public Object detail(SessionPrincipal actor,String id){commands.requireAdmin(actor);long mid=WallRules.id(id,"id");var m=mapper.message(mid,false);if(m==null)throw WallRules.missing();return Map.of("message",mapper.dto(m,actor.userId()),"status",m.status(),"reports",moderation.reports(mid,null),"history",moderation.history(mid));}
 @Transactional(readOnly=true)public Object comments(SessionPrincipal actor,String id,String cursor,int size){commands.requireAdmin(actor);long mid=WallRules.id(id,"messageId");if(mapper.message(mid,false)==null)throw WallRules.missing();WallRules.size(size);var rows=comments.list(mid,WallRules.cursor(cursor),size,true);boolean more=rows.size()>size;var items=rows.stream().limit(size).map(c->Map.of("comment",comments.dto(c,actor.userId()),"status",c.status(),"reports",moderation.reports(mid,c.id()))).toList();return new Page<>(items,more?Long.toString(rows.get(size-1).id()):null,more);}
 @Transactional(readOnly=true)public Object reports(SessionPrincipal actor,String cursor,int size){commands.requireAdmin(actor);WallRules.size(size);var rows=mapper.sql().queryForList("SELECT CAST(id AS CHAR) AS id,CAST(message_id AS CHAR) AS messageId,CAST(comment_id AS CHAR) AS commentId,target_type AS targetType,reason,detail,status,created_at AS createdAt FROM wall_report WHERE id<? ORDER BY id DESC LIMIT ?",WallRules.cursor(cursor),size+1);boolean more=rows.size()>size;var items=rows.stream().limit(size).toList();return new Page<>(items,more?items.getLast().get("id").toString():null,more);}
 @Transactional(isolation=Isolation.READ_COMMITTED)public Map<?,?> apply(SessionPrincipal actor,String id,boolean isComment,ModerationInput input){
  commands.requireAdmin(actor);if(input==null)throw WallRules.conflict();long target=WallRules.id(id,"id"),version=WallRules.version(input.expectedVersion());String action=WallRules.oneOf(input.action(),"action","EDIT","HIDE","RESTORE","DELETE","KEEP"),reason=WallRules.text(input.authorReason(),"authorReason",200,true),internal=WallRules.text(input.internalNote(),"internalNote",500,false);List<String> reports=input.reportIds()==null?List.of():input.reportIds();if(reports.size()>50||new HashSet<>(reports).size()!=reports.size())throw BusinessException.invalid("reportIds","最多选择50条不同举报");reports.forEach(r->WallRules.id(r,"reportIds"));if(isComment&&action.equals("EDIT"))throw BusinessException.invalid("action","评论支持隐藏、恢复、删除及处理举报");
  return commands.execute(actor,input.requestId(),"MODERATE_"+(isComment?"COMMENT:":"MESSAGE:")+id,input,Map.class,()->{
   mapper.lockLayout();WallInteractionMapper.Comment c=isComment?comments.comment(target,false):null;if(isComment&&c==null)throw WallRules.missing();long mid=isComment?c.messageId():target;var p=mapper.message(mid,true);if(p==null)throw WallRules.missing();if(isComment)c=comments.comment(target,true);String status=isComment?c.status():p.status();long actual=isComment?c.version():p.version();if(actual!=version)throw WallRules.conflict();if(status.equals("DELETED")&&!action.equals("KEEP"))throw WallRules.conflict();if(isComment&&p.status().equals("DELETED")&&!action.equals("KEEP"))throw WallRules.conflict();if(action.equals("HIDE")&&!status.equals("VISIBLE")||action.equals("RESTORE")&&!status.equals("HIDDEN"))throw WallRules.conflict();
   String beforeBody=isComment?c.body():p.body(),beforeTitle=isComment?"":p.title(),body=beforeBody,title=beforeTitle;if(action.equals("EDIT")){body=WallRules.text(input.text(),"text",1000,true);title=p.kind().equals("ANNOUNCEMENT")?WallRules.text(input.title(),"title",80,true):"";}
   for(String report:reports){var found=mapper.sql().queryForList("SELECT id FROM wall_report WHERE id=? AND message_id=? AND "+(isComment?"comment_id=?":"comment_id IS NULL")+" AND status='PENDING' FOR UPDATE",isComment?new Object[]{Long.parseLong(report),mid,target}:new Object[]{Long.parseLong(report),mid});if(found.isEmpty())throw BusinessException.invalid("reportIds","举报已处理或不属于当前内容");}
   String afterStatus=switch(action){case "HIDE"->"HIDDEN";case "RESTORE"->"VISIBLE";case "DELETE"->"DELETED";default->status;};var now=commands.clock.instant();
   if(isComment)mapper.sql().update("UPDATE wall_comment SET status=?,version=version+1,updated_at=? WHERE id=?",afterStatus,Timestamp.from(now),target);
   else{Position pos=action.equals("RESTORE")?WallLayout.allocate(p.x(),p.y(),mapper.occupied(mid)):new Position(p.x(),p.y(),280,420);mapper.sql().update("UPDATE wall_message SET body=?,title=?,status=?,edited_by_admin=?,position_x=?,position_y=?,version=version+1,updated_at=? WHERE id=?",body,title,afterStatus,p.edited()||action.equals("EDIT"),pos.x(),pos.y(),Timestamp.from(now),target);}
   for(String report:reports)mapper.sql().update("UPDATE wall_report SET status='RESOLVED',handled_at=? WHERE id=?",Timestamp.from(now),Long.parseLong(report));
   Long cid=isComment?target:null;long log=moderation.log(actor.userId(),mid,cid,action,json.writeValueAsString(Map.of("title",beforeTitle,"text",beforeBody)),json.writeValueAsString(Map.of("title",title,"text",body)),reason,internal,now);
   if(!action.equals("KEEP")){int length=beforeBody.codePointCount(0,beforeBody.length());String excerpt=beforeBody.substring(0,beforeBody.offsetByCodePoints(0,Math.min(120,length)));moderation.notify(isComment?c.userId():p.userId(),log,mid,cid,action,reason,excerpt,now);}
   return Map.of("id",id,"version",version+1,"status",afterStatus);
  });
 }
}
